		local Ok, Text = pcall(readfile, "yaufrjs/device.txt")
		local Saved = Ok and Clean(Text)
		if Saved then
			return Saved
		end
	end
	local Id = string.gsub(game:GetService("HttpService"):GenerateGUID(false), "%W", "")
	pcall(function()
		if makefolder then
