local LicenseUrl = "https://manchester-instead-reporting-algorithm.trycloudflare.com/api/verify"

local function ReasonText(Reason)
	if Reason == "invalid_key" then
		return "That key is not in the list"
	end
	if Reason == "disabled" then
		return "This key is turned off"
	end
	if Reason == "expired" then
		return "This key has expired"
	end
	if Reason == "hwid_mismatch" then
		return "This key is already used on another device"
	end
	if Reason == "missing_key" then
		return "Enter a key"
	end
	if Reason == "missing_hwid" then
		return "This executor did not give a device id"
	end
	if Reason == "rate" then
		return "Wait a moment and try again"
	end
	return "Activation server is not running"
end

local function HttpText(Url)
	local Request = request or http_request or (syn and syn.request)
	if Request then
		local Ok, Res = pcall(Request, {
			Url = Url,
			Method = "GET",
			Headers = { ["User-Agent"] = "Mozilla/5.0" },
		})
		if Ok and type(Res) == "table" then
			local Body = Res.Body or Res.body
			if type(Body) == "string" and Body ~= "" then
				return Body
			end
		end
	end
	local Ok, Body = pcall(function()
		return game:HttpGet(Url)
	end)
	if Ok and type(Body) == "string" then
		return Body
	end
	return ""
end

local function AskServer(Key, Id)
	local Request = request or http_request or (syn and syn.request)
	if not Request then
		return false, "This executor cannot reach the activation server"
	end
	local Http = game:GetService("HttpService")
	local Ok, Res = pcall(Request, {
		Url = LicenseUrl,
		Method = "POST",
		Headers = {
			["Content-Type"] = "application/json",
			["User-Agent"] = "Mozilla/5.0",
		},
		Body = Http:JSONEncode({ key = Key, hwid = Id }),
	})
	if not Ok or type(Res) ~= "table" then
		return false, ReasonText("down")
	end
	local Body = Res.Body or Res.body
	if type(Body) ~= "string" or Body == "" then
		return false, ReasonText("down")
	end
	local Parsed = {}
	pcall(function()
		Parsed = Http:JSONDecode(Body)
	end)
	local Code = tonumber(Res.StatusCode or Res.Status or Res.status_code)
	if Code == 200 and type(Parsed) == "table" and Parsed.ok == true then
		return true, "Checked"
	end
	return false, ReasonText(type(Parsed) == "table" and Parsed.reason or nil)
end

local function RefreshUrl()
	local Body = HttpText("https://raw.githubusercontent.com/NotYazan/yaufrjs-loader/main/url.txt")
	local Line = string.match(Body, "https://%S+")
	if not Line then
		return
	end
	Line = string.gsub(Line, "/+$", "")
	if not string.find(Line, "/api/verify", 1, true) then
		Line = Line .. "/api/verify"
	end
	LicenseUrl = Line
end

