		Method = "POST",
		Headers = {
			["Content-Type"] = "application/json",
			["User-Agent"] = "Mozilla/5.0",
		},
		Body = Http:JSONEncode({ key = Key, hwid = Id }),
	})
	if not Ok or type(Res) ~= "table" then
		return false, "Activation server is not running"
	end
	local Answer = Res.Body or Res.body
	if type(Answer) ~= "string" or Answer == "" then
		return false, "Activation server is not running"
	end
	local Parsed = {}
	pcall(function()
		Parsed = Http:JSONDecode(Answer)
	end)
	local Code = tonumber(Res.StatusCode or Res.Status or Res.status_code)
	if Code == 200 and type(Parsed) == "table" and Parsed.ok == true then
		if writefile then
			pcall(writefile, "yaufrjs/key.txt", Key)
		end
		return true, "Checked"
	end
	local Reason = type(Parsed) == "table" and Parsed.reason or ""
	if Reason == "hwid_mismatch" then
		return false, "This key is already used on another device"
	end
	if Reason == "expired" then
		return false, "This key has expired"
	end
	if Reason == "disabled" then
		return false, "This key is turned off"
	end
	if Reason == "invalid_key" then
		return false, "That key is not in the list"
	end
	return false, "Activation server is not running"
end
local function OpenDiscord()
	local function Try(Fn)
		if type(Fn) ~= "function" then
			return false
		end
		return pcall(Fn, DiscordUrl)
	end
	if type(syn) == "table" and Try(syn.open_url) then
		return true
	end
	if Try(openurl) or Try(OpenUrl) then
		return true
	end
	local Ok = pcall(function()
		game:GetService("GuiService"):OpenBrowserWindow(DiscordUrl)
	end)
	return Ok
end
